const files = {"src/lib/ai/demo-simulation.ts": "import type { AIPromptRequest, AIPromptResponse } from '@/types/ai';\nexport class DemoPromptError extends Error { readonly status = 422; }\ntype Lang = 'en' | 'yo' | 'ha' | 'ig';\nconst copy = {\n  en: {\n    title: 'Free demo · Projectile motion',\n    description: 'Projectile parameters read from supported text patterns, without an AI service.',\n    note: 'Free rule-based demo, not generative AI. Ignoring air resistance, horizontal velocity is constant and gravity accelerates the projectile downward. Unspecified values use the defaults shown below. Launch and landing are at equal heights.',\n    values: 'Parameters', defaults: 'Defaults used', none: 'none',\n    unsupported: 'This free homepage demo supports projectile motion only. Try: \"Show projectile motion at 45° and 30 m/s\". Open the simulations catalogue for other topics.',\n    numbers: 'Some numbers could not be interpreted, or a parameter was repeated. Use explicit units: 30 m/s, 45°, gravity 9.81 m/s², mass 1 kg.',\n    range: 'Use speed 1–100 m/s, angle 1–89°, gravity 1–25 m/s² and mass 0.1–100 kg, matching the homepage controls.',\n    planet: 'For another planet or the Moon, specify gravity numerically (for example: gravity 2 m/s²). The demo does not infer planetary gravity.',\n  },\n  yo: {\n    title: 'Àpẹẹrẹ ọ̀fẹ́ · Projectile motion',\n    description: 'A ka àwọn iye projectile láti inú àpẹẹrẹ ọ̀rọ̀, láìlo iṣẹ́ AI.',\n    note: 'Àpẹẹrẹ tó ń lo òfin ni èyí; kì í ṣe AI tó ń dá ìdáhùn tuntun. Láìka ìdènà afẹ́fẹ́ sí, velocity petele kì í yí padà; gravity ń fa ohun náà sísàlẹ̀. Bí o kò bá sọ iye kan, a lo iye àkọ́kọ́ tó wà nísàlẹ̀. Ibi ìfilọ́lẹ̀ àti ibi ìbalẹ̀ ga bákan náà.',\n    values: 'Àwọn iye', defaults: 'Iye àkọ́kọ́ tí a lò', none: 'kò sí',\n    unsupported: 'Àpẹẹrẹ ọ̀fẹ́ ojú ìwé yìí ń ṣe projectile motion nìkan. Gbìyànjú: \"Ṣe afihan projectile ni 45° ati 30 m/s\". Ṣí àkójọ simulation fún kókó mìíràn.',\n    numbers: 'A kò lè túmọ̀ díẹ̀ nínú àwọn nọ́mbà, tàbí o tún iye kan sọ. Lo unit kedere: 30 m/s, 45°, gravity 9.81 m/s², mass 1 kg.',\n    range: 'Lo speed 1–100 m/s, igun 1–89°, gravity 1–25 m/s² àti mass 0.1–100 kg, gẹ́gẹ́ bí àwọn controls ojú ìwé.',\n    planet: 'Fún planet mìíràn tàbí Òṣùpá, kọ iye gravity pẹ̀lú nọ́mbà. Àpẹẹrẹ yìí kò lè mọ gravity planet fúnra rẹ̀.',\n  },\n  ha: {\n    title: 'Samfurin kyauta · Projectile motion',\n    description: 'Ana karanta ma’aunin projectile daga tsarin rubutu ba tare da sabis na AI ba.',\n    note: 'Wannan samfurin yana amfani da ƙa’idoji; ba AI mai samar da sabbin amsoshi ba ne. Ba tare da juriyar iska ba, gudun kwance ba ya sauyawa, gravity kuma yana hanzarta abin zuwa ƙasa. Abin da ba ka bayyana ba yana amfani da ma’aunin farko da aka nuna a ƙasa. Tsayin farawa da na sauka ɗaya ne.',\n    values: 'Ma’aunai', defaults: 'Ma’aunin farko da aka yi amfani da shi', none: 'babu',\n    unsupported: 'Wannan samfurin shafin farko yana goyon bayan projectile motion kawai. Gwada: \"Nuna projectile a 45° da 30 m/s\". Buɗe jerin simulations don sauran batutuwa.',\n    numbers: 'An kasa fahimtar wasu lambobi, ko an maimaita ma’auni. Yi amfani da units: 30 m/s, 45°, gravity 9.81 m/s², mass 1 kg.',\n    range: 'Yi amfani da gudu 1–100 m/s, kusurwa 1–89°, gravity 1–25 m/s² da mass 0.1–100 kg, kamar controls na shafin.',\n    planet: 'Don wata duniya ko Wata, ka rubuta gravity da lamba. Wannan samfurin ba ya gano gravity na duniya da kansa.',\n  },\n  ig: {\n    title: 'Ihe ngosi efu · Projectile motion',\n    description: 'A na-agụ ụkpụrụ projectile site n’usoro ederede na-enweghị ọrụ AI.',\n    note: 'Ihe ngosi a na-eji iwu edoziri; ọ bụghị AI na-emepụta azịza ọhụrụ. Mgbe mgbochi ikuku adịghị, velocity kwụ ọtọ n’ala anaghị agbanwe; gravity na-eme ka ihe ahụ gaa ala ngwa ngwa. Ihe ị na-akọwaghị na-eji ụkpụrụ mbido e depụtara n’okpuru. Ebe mbido na ebe ọdịda nọ n’otu ịdị elu.',\n    values: 'Ụkpụrụ', defaults: 'Ụkpụrụ mbido e ji mee ihe', none: 'ọ dịghị',\n    unsupported: 'Ihe ngosi efu na peeji a na-akwado naanị projectile motion. Gbalịa: \"Gosi projectile na 45° na 30 m/s\". Mepee ndepụta simulations maka ihe ndị ọzọ.',\n    numbers: 'Aghọtaghị ụfọdụ ọnụọgụ, ma ọ bụ i degharịrị otu ụkpụrụ. Jiri units doro anya: 30 m/s, 45°, gravity 9.81 m/s², mass 1 kg.',\n    range: 'Jiri speed 1–100 m/s, nkuku 1–89°, gravity 1–25 m/s² na mass 0.1–100 kg, dịka controls dị na peeji a.',\n    planet: 'Maka planet ọzọ ma ọ bụ Ọnwa, dee gravity n’ọnụọgụ. Ihe ngosi a anaghị achọpụta gravity planet n’onwe ya.',\n  },\n};\nexport function parseDemoSimulation(request: AIPromptRequest): AIPromptResponse & { mode: 'demo' } {\n  if (request.language && !['en', 'yo', 'ha', 'ig'].includes(request.language)) throw new DemoPromptError('The free demo supports English, Yoruba, Hausa and Igbo.');\n  const language = (request.language || 'en') as Lang;\n  const c = copy[language];\n  const text = request.prompt.normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase();\n  if (!/\\b(projectile|projectiles)\\b/.test(text) || /\\b(newton|ohm|circuit|circular|pendulum|wave|friction|wind|drag|resistance)\\b/.test(text)) throw new DemoPromptError(c.unsupported);\n  const params = { initialVelocity: 20, angle: 45, gravity: 9.81, mass: 1 };\n  type Key = keyof typeof params;\n  const specified = new Set<Key>();\n  let remaining = text;\n  const number = '([-+]?(?:\\\\d+(?:\\\\.\\\\d*)?|\\\\.\\\\d+)(?:e[-+]?\\\\d+)?)';\n  function read(key: Key, expression: string) {\n    remaining = remaining.replace(new RegExp(expression, 'g'), (whole, value: string) => {\n      if (specified.has(key)) throw new DemoPromptError(c.numbers);\n      const n = Number(value); if (!Number.isFinite(n)) throw new DemoPromptError(c.numbers);\n      params[key] = n; specified.add(key); return ' '.repeat(whole.length);\n    });\n  }\n  // Parse acceleration before speed, so m/s² is never interpreted as velocity.\n  read('gravity', `(?:gravity|gravitational acceleration|g)\\\\s*(?:=|:|of|ni|a|na)?\\\\s*${number}\\\\s*(?:m\\\\s*\\\\/\\\\s*s(?:²|\\\\^2|2))?`);\n  read('gravity', `${number}\\\\s*m\\\\s*\\\\/\\\\s*s(?:²|\\\\^\\\\s*2|2)`);\n  read('initialVelocity', `${number}\\\\s*(?:m\\\\s*\\\\/\\\\s*s|mps|met(?:er|re)s? per second)(?![a-z0-9²^])`);\n  read('initialVelocity', `(?:speed|velocity|gudu)\\\\s*(?:=|:|of|ni|a|na)?\\\\s*${number}(?![\\\\d.])`);\n  read('angle', `${number}\\\\s*(?:°|degrees?|deg|digiri)(?![a-z])`);\n  read('angle', `(?:angle|igun|kusurwa|nkuku)\\\\s*(?:=|:|of|ni|a|na)?\\\\s*${number}(?![\\\\d.])`);\n  read('mass', `${number}\\\\s*(?:kg|kilograms?)(?![a-z])`);\n  read('mass', `mass\\\\s*(?:=|:|of|ni|a|na)?\\\\s*${number}(?![\\\\d.])`);\n  if (/\\d/.test(remaining)) throw new DemoPromptError(c.numbers);\n  if (/\\b(moon|mars|venus|jupiter|mercury|saturn|uranus|neptune)\\b/.test(text) && !specified.has('gravity')) throw new DemoPromptError(c.planet);\n  if (params.initialVelocity < 1 || params.initialVelocity > 100 || params.angle < 1 || params.angle > 89 || params.gravity < 1 || params.gravity > 25 || params.mass < .1 || params.mass > 100) throw new DemoPromptError(c.range);\n  const defaults = (Object.keys(params) as Key[]).filter(k => !specified.has(k));\n  return {\n    mode: 'demo', simulationType: 'projectile_motion', title: c.title,\n    description: c.description, params,\n    explanation: `${c.note}\\n${c.values}: u = ${params.initialVelocity} m/s; θ = ${params.angle}°; g = ${params.gravity} m/s²; m = ${params.mass} kg. ${c.defaults}: ${defaults.length ? defaults.join(', ') : c.none}.`,\n    suggestedFollowUps: [],\n  };\n}\n", "src/lib/ai/parse-prompt.ts": "import Anthropic from '@anthropic-ai/sdk';\nimport type { AIPromptRequest, AIPromptResponse } from '@/types/ai';\n\nimport { parseDemoSimulation } from './demo-simulation';\n\nconst SYSTEM_PROMPT = `You are the AI engine for A-Factor STEM Studio, a STEM simulation platform for African secondary schools (WAEC/NECO/JAMB curriculum).\n\nWhen a user describes a physics concept or asks to simulate something, extract the simulation parameters and return a JSON object ONLY — no markdown, no explanation outside the JSON.\n\nSupported simulation types: projectile_motion, newtons_second_law, circular_motion, simple_harmonic_motion, ohms_law, simple_circuit\n\nReturn this exact JSON shape:\n{\n  \"simulationType\": \"<type>\",\n  \"title\": \"<short title>\",\n  \"description\": \"<one sentence>\",\n  \"params\": {},\n  \"explanation\": \"<2-3 sentence plain English explanation>\",\n  \"suggestedFollowUps\": [\"<q1>\", \"<q2>\", \"<q3>\"]\n}\n\nFor projectile_motion params: initialVelocity (m/s), angle (degrees), gravity (m/s², default 9.81), mass (kg, default 1)\nFor newtons_second_law params: mass (kg), force (N), friction (0-1)\n\nIf the user writes in Yoruba, Hausa, or Igbo, respond with explanation in that language but keep JSON keys in English.`;\n\nexport async function parseSimulationPrompt(request: AIPromptRequest): Promise<AIPromptResponse & { mode: 'demo' | 'live' }> {\n  // Free local parsing is the default, even when an old/invalid key exists.\n  if (process.env.SIMULATION_AI_MODE !== 'live') return parseDemoSimulation(request);\n  if (!process.env.ANTHROPIC_API_KEY) throw new Error('LIVE_AI_NOT_CONFIGURED');\n  const result = await parseLiveSimulationPrompt(request);\n  return { ...result, mode: 'live' };\n}\n\nasync function parseLiveSimulationPrompt(request: AIPromptRequest): Promise<AIPromptResponse> {\n  const client = new Anthropic({ timeout: 22000, maxRetries: 0 });\n  const message = await client.messages.create({\n    model: 'claude-sonnet-4-6',\n    max_tokens: 1024,\n    system: SYSTEM_PROMPT,\n    messages: [{ role: 'user', content: request.prompt }],\n  });\n  const content = message.content[0];\n  if (content.type !== 'text') throw new Error('Unexpected response type');\n  const cleaned = content.text.replace(/```json|```/g, '').trim();\n  return JSON.parse(cleaned) as AIPromptResponse;\n}\n", "src/app/api/ai/route.ts": "import { NextRequest, NextResponse } from 'next/server';\nimport { parseSimulationPrompt } from '@/lib/ai/parse-prompt';\nimport { DemoPromptError } from '@/lib/ai/demo-simulation';\nimport type { AIPromptRequest } from '@/types/ai';\nexport async function POST(req: NextRequest) {\n  let body: unknown;\n  try {\n    const text = await req.text();\n    if (text.length > 4000) return NextResponse.json({ error: 'Request too large.' }, { status: 413 });\n    body = JSON.parse(text);\n  } catch { return NextResponse.json({ error: 'Invalid JSON.' }, { status: 400 }); }\n  if (!body || typeof body !== 'object') return NextResponse.json({ error: 'Invalid request.' }, { status: 400 });\n  const { prompt, language } = body as { prompt?: unknown; language?: unknown };\n  if (typeof prompt !== 'string' || !prompt.trim()) return NextResponse.json({ error: 'Prompt is required.' }, { status: 400 });\n  if (prompt.length > 500) return NextResponse.json({ error: 'Prompt too long.' }, { status: 400 });\n  if (language !== undefined && !['en','yo','ha','ig','fr','ar'].includes(language as string)) return NextResponse.json({ error: 'Invalid language.' }, { status: 400 });\n  try {\n    const result = await parseSimulationPrompt({ prompt: prompt.trim(), language } as AIPromptRequest);\n    return NextResponse.json(result, { headers: { 'Cache-Control': 'no-store' } });\n  } catch (error) {\n    if (error instanceof DemoPromptError) return NextResponse.json({ error: error.message, mode: 'demo' }, { status: 422 });\n    // Do not print credentials, provider response headers or request contents.\n    const status = error && typeof error === 'object' && 'status' in error ? error.status : undefined;\n    if (status === 401) return NextResponse.json({ error: 'Live AI rejected the API key. Use SIMULATION_AI_MODE=demo for the free demo, then restart your server.' }, { status: 502 });\n    return NextResponse.json({ error: 'Live AI is unavailable. Set SIMULATION_AI_MODE=demo and restart for the free demo.' }, { status: 503 });\n  }\n}\n", "src/components/ai/PromptBar.tsx": "'use client';\nimport { useEffect, useRef, useState } from 'react';\nimport type { AIPromptResponse } from '@/types/ai';\ntype Language = 'en' | 'yo' | 'ha' | 'ig';\ninterface PromptBarProps { onResult: (r: AIPromptResponse) => void; className?: string; }\nconst languages = { en: 'English', yo: 'Yorùbá', ha: 'Hausa', ig: 'Igbo' };\nconst labels = {\n  en: { language: 'Response language', placeholder: 'Example: projectile at 45° and 30 m/s', generate: 'Apply prompt', loading: 'Reading…', note: 'Free demo: reads supported projectile prompts using rules. No AI API key needed. Other topics are available in the simulations catalogue.', demo: 'Free demo response · no AI service called', live: 'Live AI response' },\n  yo: { language: 'Èdè ìdáhùn', placeholder: 'Àpẹẹrẹ: Ṣe afihan projectile ni 45° ati 30 m/s', generate: 'Lo ìbéèrè', loading: 'Ó ń kà á…', note: 'Àpẹẹrẹ ọ̀fẹ́: ó ń lo òfin láti ka ìbéèrè projectile. Kò nílò API key. Àwọn kókó mìíràn wà nínú àkójọ simulation.', demo: 'Ìdáhùn àpẹẹrẹ ọ̀fẹ́ · a kò lo iṣẹ́ AI', live: 'Ìdáhùn AI' },\n  ha: { language: 'Harshen amsa', placeholder: 'Misali: Nuna projectile a 45° da 30 m/s', generate: 'Aiwatar', loading: 'Ana karantawa…', note: 'Samfurin kyauta: yana karanta tambayar projectile da ƙa’idoji. Ba ya buƙatar API key. Sauran batutuwa suna cikin jerin simulations.', demo: 'Amsar samfurin kyauta · ba a kira sabis na AI ba', live: 'Amsar AI' },\n  ig: { language: 'Asụsụ azịza', placeholder: 'Ihe atụ: Gosi projectile na 45° na 30 m/s', generate: 'Tinye arịrịọ', loading: 'A na-agụ…', note: 'Ihe ngosi efu: ọ na-eji iwu agụ arịrịọ projectile. Ọ chọghị API key. Ihe ndị ọzọ dị na ndepụta simulations.', demo: 'Azịza ihe ngosi efu · ejighị ọrụ AI', live: 'Azịza AI' },\n};\nconst examples: Record<Language, string[]> = {\n  en: ['Show projectile motion at 45° and 30 m/s', 'Show projectile motion at 60° and 20 m/s', 'Projectile at 30 m/s, 30°, gravity 2 m/s², mass 2 kg'],\n  yo: ['Ṣe afihan projectile ni 45° ati 30 m/s', 'Ṣe afihan projectile ni 60° ati 20 m/s', 'Projectile ni 30 m/s, 30°, gravity 2 m/s², mass 2 kg'],\n  ha: ['Nuna projectile a 45° da 30 m/s', 'Nuna projectile a 60° da 20 m/s', 'Projectile a 30 m/s, 30°, gravity 2 m/s², mass 2 kg'],\n  ig: ['Gosi projectile na 45° na 30 m/s', 'Gosi projectile na 60° na 20 m/s', 'Projectile na 30 m/s, 30°, gravity 2 m/s², mass 2 kg'],\n};\nexport function PromptBar({ onResult, className }: PromptBarProps) {\n  const [prompt, setPrompt] = useState('');\n  const [language, setLanguage] = useState<Language>('en');\n  const [isLoading, setIsLoading] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [mode, setMode] = useState<'demo' | 'live' | null>(null);\n  const pending = useRef<AbortController | null>(null);\n  const ui = labels[language];\n  useEffect(() => {\n    try { const saved = localStorage.getItem('afactor-simulation-language-v1'); if (saved && saved in languages) setLanguage(saved as Language); } catch { /* storage is optional */ }\n    return () => pending.current?.abort();\n  }, []);\n  function changeLanguage(value: Language) {\n    pending.current?.abort(); pending.current = null; setIsLoading(false);\n    setLanguage(value); setError(null); setMode(null);\n    try { localStorage.setItem('afactor-simulation-language-v1', value); } catch { /* storage is optional */ }\n  }\n  async function handleSubmit(text: string) {\n    if (!text.trim() || isLoading) return;\n    const controller = new AbortController(); pending.current = controller;\n    setIsLoading(true); setError(null); setMode(null);\n    const timeout = setTimeout(() => controller.abort(), 28000);\n    try {\n      const res = await fetch('/api/ai', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ prompt: text, language }), signal: controller.signal });\n      const result = await res.json();\n      if (!res.ok) throw new Error(result.error || 'Unable to read this prompt.');\n      if (pending.current !== controller) return;\n      onResult(result); setMode(result.mode === 'demo' ? 'demo' : 'live'); setPrompt('');\n    } catch (err) {\n      if (pending.current === controller) setError(controller.signal.aborted ? 'Request timed out. Try again.' : err instanceof Error ? err.message : 'Unable to read this prompt.');\n    } finally { clearTimeout(timeout); if (pending.current === controller) { pending.current = null; setIsLoading(false); } }\n  }\n  return <div className={className}>\n    <div className=\"mb-3 flex flex-wrap items-center gap-3\"><label className=\"text-xs font-semibold text-gray-700\">{ui.language}<select aria-label={ui.language} value={language} onChange={e => changeLanguage(e.target.value as Language)} className=\"ml-2 rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900\">{Object.entries(languages).map(([id, name]) => <option key={id} value={id}>{name}</option>)}</select></label></div>\n    <p className=\"mb-3 text-xs leading-6 text-gray-700\" lang={language}>{ui.note}</p>\n    <div className=\"flex flex-col gap-2 sm:flex-row\"><input aria-label={ui.placeholder} type=\"text\" value={prompt} maxLength={500} onChange={e => setPrompt(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); void handleSubmit(prompt); } }} placeholder={ui.placeholder} disabled={isLoading} className=\"min-w-0 flex-1 rounded-lg border border-gray-300 bg-white px-4 py-3 text-base text-gray-900 outline-none placeholder:text-gray-600 focus:border-indigo-500 disabled:opacity-50 sm:text-sm\" /><button onClick={() => void handleSubmit(prompt)} disabled={!prompt.trim() || isLoading} className=\"w-full shrink-0 rounded-lg bg-indigo-600 px-5 py-3 text-sm font-medium text-white hover:bg-indigo-700 disabled:opacity-50 sm:w-auto\">{isLoading ? ui.loading : ui.generate}</button></div>\n    {error && <p role=\"alert\" className=\"mt-2 text-sm text-red-800\">{error}</p>}\n    {mode && <p role=\"status\" lang={language} className=\"mt-2 text-xs font-semibold text-emerald-800\">{mode === 'demo' ? ui.demo : ui.live}</p>}\n    <div className=\"mt-3 flex flex-wrap gap-2\">{examples[language].map(p => <button key={p} onClick={() => void handleSubmit(p)} disabled={isLoading} className=\"max-w-full rounded-xl border border-gray-300 bg-gray-50 px-3 py-2 text-left text-xs leading-5 text-gray-700 hover:border-indigo-400 disabled:opacity-50\">{p}</button>)}</div>\n  </div>;\n}\n", "capstone/FREE_SIMULATION_PROMPTS.md": "# Free /api/ai simulation demo\n\nInstall from the project root with `bash patch-ai-free-demo.sh`, then stop the dev server (Ctrl+C) and restart with `npm run dev`. Open the homepage at http://localhost:3000.\n\nThe default is now the free rule-based parser, independent of whether ANTHROPIC_API_KEY is missing or invalid. No Anthropic request is made in demo mode. It reads numeric settings; it is not a generative model. It requires a running Next.js server, but no paid API for these prompts.\n\nChoose English, Yoruba, Hausa or Igbo in the prompt bar. Click a sample or enter a projectile prompt with clear units. The explanation uses the selected response language. The rest of the simulation interface is unchanged. Language wording is draft content for fluent-teacher review.\n\nSupported examples:\n\n- Show projectile motion at 45° and 30 m/s\n- Ṣe afihan projectile ni 45° ati 30 m/s\n- Nuna projectile a 45° da 30 m/s\n- Gosi projectile na 45° na 30 m/s\n- Projectile at 30 m/s, 30°, gravity 2 m/s², mass 2 kg\n\nThe word `projectile` is a supported keyword in all four languages. English parameter names and SI symbols are retained. The parser does not understand arbitrary language or word-based numbers. Select the response language explicitly; it does not infer language from your question.\n\nDefaults for omitted settings: speed 20 m/s; angle 45°; gravity 9.81 m/s²; mass 1 kg. The response lists defaults used. Limits match homepage controls: speed 1–100 m/s, angle 1–89°, gravity 1–25 m/s², mass 0.1–100 kg. Unsupported numeric values and repeated settings return a clear error without changing the current simulation.\n\nScope: homepage projectile motion only, with no air resistance and equal launch/landing heights. Other simulations remain in the simulations catalogue. The old Newton-law example was removed because this homepage does not display that scene. The patch does not generate new simulations or answer general STEM questions. Use the separate /tutor guided demo for prepared lesson responses.\n\n## Environment\n\nNo environment change is normally needed. To explicitly select free mode in `.env.local`:\n\n```\nSIMULATION_AI_MODE=demo\n```\n\nOnly `SIMULATION_AI_MODE=live` enables the existing paid Anthropic integration. Do not set that for this free demo. If using a deployed site, apply the code changes and redeploy; set the same mode there if previously overridden. This patch does not repair or validate the old API key. Demo mode bypasses it. It does not change the separate /api/tutor endpoint.\n\n## Validation\n\nTypeScript and production build checks passed. Automated parser checks covered English, Yoruba, Hausa and Igbo examples; degree and acceleration formats; defaults; invalid bounds; unknown numerical input; duplicate settings; unsupported topics; and the default path with a deliberately invalid key and blocked external fetch. Browser interaction testing remains unverified.\n"};
if (!fs.existsSync('package.json') || !fs.existsSync('src/app/api/ai/route.ts') || !fs.existsSync('src/lib/ai/parse-prompt.ts') || !fs.existsSync('src/app/page.tsx')) {
 console.error('Run from the root of your project where package.json and src/ are located. No files changed.');process.exit(1);
